n          <i class=\"fas fa-trash text-xs\" />\n        </button>\n      </div>\n    </div>\n\n    <div\n      v-if=\"!folder.collapsed\"\n      class=\"folder-items\"\n      @dragover.prevent=\"onDragOver\"\n      @dragleave=\"isDragOver = false\"\n      @drop.prevent=\"onDrop\"\n      :class=\"{ 'drag-over': isDragOver }\"\n    >\n      <div v-if=\"!folder.items.length\" class=\"empty-folder text-slate-600 text-xs text-center py-2\">\n        拖拽条目到此处\n      </div>\n      <div\n        v-for=\"(item, i) in folder.items\"\n        :key=\"`${folder.id}-${i}`\"\n        class=\"fav-item\"\n        :draggable=\"true\"\n        @dragstart=\"onItemDragStart($event, item, i)\"\n      >\n        <span class=\"fav-item-name\">{{ item.name }}</span>\n        <button class=\"fav-remove-btn\" title=\"移除\" @click=\"store.removeFromFavorites(folder.id, i)\">\n          <i class=\"fas fa-times text-xs\" />\n        </button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useManagerStore, type FavoriteFolder } from '../stores/manager';\n\nconst props = defineProps<{\n  folder: FavoriteFolder;\n}>();\n\nconst emit = defineEmits<{\n  delete: [];\n}>();\n\nconst store = useManagerStore();\nconst isEditing = ref(false);\nconst editName = ref('');\nconst nameInput = ref<HTMLInputElement>();\nconst isDragOver = ref(false);\n\nfunction startEdit() {\n  editName.value = props.folder.name;\n  isEditing.value = true;\n  nextTick(() => nameInput.value?.focus());\n}\n\nfunction finishEdit() {\n  if (isEditing.value && editName.value.trim()) {\n    store.renameFavoriteFolder(props.folder.id, editName.value.trim());\n  }\n  isEditing.value = false;\n}\n\nfunction cancelEdit() {\n  isEditing.value = false;\n}\n\nfunction onDragOver(e: DragEvent) {\n  e.dataTransfer!.dropEffect = 'copy';\n  isDragOver.value = true;\n}\n\nfunction onDrop(e: DragEvent) {\n  isDragOver.value = false;\n  const raw = e.dataTransfer?.getData('application/json');\n  if (!raw) return;\n\n  try {\n    const data = JSON.parse(raw);\n    const prompt = data.prompt as PresetPrompt;\n    if (!prompt || isPresetPlaceholderPrompt(prompt)) return;\n\n    store.addToFavorites(props.folder.id, {\n      id: prompt.id,\n      name: prompt.name,\n      enabled: prompt.enabled ?? true,\n      position: (prompt as any).position ?? { type: 'relative' as const },\n      role: prompt.role,\n      content: (prompt as any).content ?? '',\n    });\n\n    toastr.success(`已收藏 \"${prompt.name}\"`, '', { timeOut: 1500 });\n  } catch (err) {\n    console.error('[FavoriteFolder] Drop error:', err);\n  }\n}\n\nfunction onItemDragStart(e: DragEvent, item: PresetNormalPrompt, index: number) {\n  e.dataTransfer!.effectAllowed = 'copy';\n  e.dataTransfer!.setData(\n    'application/json',\n    JSON.stringify({\n      type: 'favorite',\n      source: props.folder.id,\n      index,\n      prompt: item,\n    }),\n  );\n}\n</script>\n\n<style scoped>\n.favorite-folder {\n  border: 1px solid rgba(51, 65, 85, 0.3);\n  border-radius: 6px;\n  background: rgba(15, 23, 42, 0.4);\n  overflow: hidden;\n}\n.folder-header {\n  display: flex;\n  align-items: center;\n  padding: 6px 8px;\n  cursor: pointer;\n  gap: 4px;\n}\n.folder-header:hover {\n  background: rgba(51, 65, 85, 0.2);\n}\n.folder-name {\n  font-size: 12px;\n  color: #cbd5e1;\n  font-weight: 500;\n}\n.folder-name-input {\n  flex: 1;\n  padding: 1px 6px;\n  border-radius: 4px;\n  border: 1px solid rgba(99, 102, 241, 0.5);\n  background: rgba(0, 0, 0, 0.3);\n  color: #e2e8f0;\n  font-size: 12px;\n  outline: none;\n}\n.folder-actions {\n  display: flex;\n  gap: 2px;\n  opacity: 0;\n  transition: opacity 0.12s;\n}\n.folder-header:hover .folder-actions {\n  opacity: 1;\n}\n.folder-btn {\n  width: 20px;\n  height: 20px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: #64748b;\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.folder-btn:hover {\n  color: #94a3b8;\n  background: rgba(51, 65, 85, 0.4);\n}\n.folder-items {\n  padding: 2px 6px 6px;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  transition: background 0.15s;\n  min-height: 24px;\n}\n.folder-items.drag-over {\n  background: rgba(99, 102, 241, 0.05);\n}\n.fav-item {\n  display: flex;\n  align-items: center;\n  padding: 4px 8px;\n  border-radius: 5px;\n  background: rgba(30, 41, 59, 0.5);\n  border: 1px solid rgba(51, 65, 85, 0.3);\n  cursor: grab;\n  gap: 4px;\n}\n.fav-item:hover {\n  border-color: rgba(99, 102, 241, 0.3);\n}\n.fav-item-name {\n  flex: 1;\n  font-size: 11px;\n  color: #cbd5e1;\n  word-break: break-all;\n}\n.fav-remove-btn {\n  width: 18px;\n  height: 18px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 3px;\n  border: none;\n  background: transparent;\n  color: #475569;\n  cursor: pointer;\n  flex-shrink: 0;\n  opacity: 0;\n  transition: all 0.12s;\n}\n.fav-item:hover .fav-remove-btn {\n  opacity: 1;\n}\n.fav-remove-btn:hover {\n  color: #f87171;\n  background: rgba(248, 113, 113, 0.1);\n}\n</style>\n"],"sourceRoot":""}]);
