dataTransfer!.effectAllowed = 'copy';\n  e.dataTransfer!.setData(\n    'application/json',\n    JSON.stringify({\n      type: props.dragType ?? 'prompt',\n      source: props.dragSource ?? '',\n      index: props.dragIndex ?? 0,\n      prompt: props.prompt,\n    }),\n  );\n}\n\nfunction onDragEnd() {\n  isDragging.value = false;\n}\n\ndefineExpose({ expanded });\n</script>\n\n<style scoped>\n.prompt-item {\n  border: 1px solid rgba(51, 65, 85, 0.4);\n  border-radius: 8px;\n  background: rgba(15, 23, 42, 0.6);\n  transition: all 0.15s;\n  cursor: grab;\n}\n.prompt-item:hover {\n  border-color: rgba(99, 102, 241, 0.3);\n  background: rgba(15, 23, 42, 0.8);\n}\n.prompt-item.dragging {\n  opacity: 0.5;\n  cursor: grabbing;\n}\n.prompt-item.is-placeholder {\n  cursor: default;\n  border-style: dashed;\n  opacity: 0.7;\n}\n.prompt-header {\n  display: flex;\n  align-items: center;\n  padding: 8px 10px;\n  cursor: pointer;\n  gap: 8px;\n}\n.prompt-name {\n  font-size: 13px;\n  color: #e2e8f0;\n  word-break: break-all;\n}\n.star-btn {\n  width: 20px;\n  height: 20px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: #64748b;\n  cursor: pointer;\n  flex-shrink: 0;\n  transition: all 0.15s;\n}\n.star-btn:hover {\n  color: #fbbf24;\n  background: rgba(251, 191, 36, 0.1);\n}\n.star-btn.favorited {\n  color: #fbbf24;\n}\n.role-badge {\n  font-size: 10px;\n  padding: 1px 6px;\n  border-radius: 4px;\n  font-weight: 500;\n  text-transform: uppercase;\n}\n.role-badge.system {\n  background: rgba(99, 102, 241, 0.15);\n  color: #818cf8;\n}\n.role-badge.user {\n  background: rgba(34, 197, 94, 0.15);\n  color: #4ade80;\n}\n.role-badge.assistant {\n  background: rgba(251, 146, 60, 0.15);\n  color: #fb923c;\n}\n.status-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: #475569;\n}\n.status-dot.enabled {\n  background: #4ade80;\n}\n.prompt-body {\n  padding: 0 10px 10px;\n  border-top: 1px solid rgba(51, 65, 85, 0.3);\n  margin-top: 0;\n  padding-top: 8px;\n}\n.content-preview {\n  font-size: 12px;\n  color: #94a3b8;\n  line-height: 1.5;\n  max-height: 120px;\n  overflow-y: auto;\n  white-space: pre-wrap;\n  word-break: break-all;\n  background: rgba(0, 0, 0, 0.2);\n  border-radius: 6px;\n  padding: 8px;\n}\n.prompt-actions {\n  display: flex;\n  gap: 6px;\n  margin-top: 8px;\n}\n.action-btn {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 4px 8px;\n  border-radius: 5px;\n  border: 1px solid rgba(51, 65, 85, 0.4);\n  background: rgba(30, 41, 59, 0.6);\n  color: #94a3b8;\n  font-size: 11px;\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.action-btn:hover {\n  background: rgba(51, 65, 85, 0.6);\n  color: #e2e8f0;\n  border-color: rgba(99, 102, 241, 0.4);\n}\n</style>\n"],"sourceRoot":""}]);
