const STORAGE_KEY = 'preset_manager';
function loadAiConfig() {
    try {
        const vars = getVariables({ type: 'script' });
        return (vars?.[STORAGE_KEY]?.aiConfig ?? {
            apiUrl: '',
            key: '',
            model: '',
            source: 'openai',
            useProxyPreset: false,
            proxyPreset: '',
        });
    }
    catch {
        return { apiUrl: '', key: '', model: '', source: 'openai', useProxyPreset: false, proxyPreset: '' };
    }
}
function saveAiConfig(config) {
    try {
        updateVariablesWith(vars => {
            _.set(vars, `${STORAGE_KEY}.aiConfig`, klona(config));
            return vars;
        }, { type: 'script' });
    }
    catch (e) {
        console.error('[PresetManager] Failed to save AI config:', e);
    }
}
export const useAiStore = defineStore('ai', {
    state: () => ({
        config: loadAiConfig(),
        messages: [],
        isGenerating: false,
        showConfig: false,
        mode: 'drawer',
        drawerHeight: 200,
        detachedPosition: { x: 100, y: 100 },
        snappedEdge: null,
        visible: false,
    }),
    actions: {
        saveConfig() {
            saveAiConfig(this.config);
        },
        toggleVisible() {
            this.visible = !this.visible;
        },
        setMode(mode) {
            this.mode = mode;
        },
        snapToEdge(edge) {
            this.snappedEdge = edge;
        },
        async sendMessage(content, presetContext) {
            if (!content.trim() || this.isGenerating)
                return;
            this.messages.push({
                id: `msg_${Date.now()}`,
                role: 'user',
                content,
                timestamp: Date.now(),
            });
            this.isGenerating = true;
            try {
                const systemPrompt = dedent `
          你是一个预设管理助手，帮助用户管理和优化 SillyTavern 的预设提示词。
          你了解各种预设的思维链语法、提示词排列最佳实践。
          用户可能会请你分析预设结构、建议条目排列顺序、生成新条目、或修改现有条目。
          请用中文回复，保持简洁实用。
          ${presetContext ? `\n当前预设上下文:\n${presetContext}` : ''}
        `;
                const chatHistory = this.messages.map(m => ({
                    role: m.role,
                    content: m.content,
                }));
                const customApi = {};
                if (this.config.useProxyPreset && this.config.proxyPreset) {
                    customApi.proxy_preset = this.config.proxyPreset;
                }
                else if (this.config.apiUrl) {
                    customApi.apiurl = this.config.apiUrl;
                    if (this.config.key)
                        customApi.key = this.config.key;
                    if (this.config.source)
                        customApi.source = this.config.source;
                }
                if (this.config.model)
                    customApi.model = this.config.model;
                const result = await generateRaw({
                    should_silence: true,
                    ordered_prompts: [
                        { role: 'system', content: systemPrompt },
                        ...chatHistory,
                    ],
                    ...(Object.keys(customApi).length > 0 ? { custom_api: customApi } : {}),
                });
                const text = typeof result === 'string' ? result : result.content;
                this.messages.push({
                    id: `msg_${Date.now()}`,
                    role: 'assistant',
                    content: text,
                    timestamp: Date.now(),
                });
            }
            catch (e) {
                this.messages.push({
                    id: `msg_${Date.now()}`,
                    role: 'assistant',
                    content: `错误: ${e?.message ?? '生成失败'}`,
                    timestamp: Date.now(),
                });
            }
            finally {
                this.isGenerating = false;
            }
        },
        clearMessages() {
            this.messages = [];
        },
    },
});
